import { generateText, wrapLanguageModel, simulateReadableStream } from 'ai';
import { openai } from '@ai-sdk/openai';

const cache = new Map<string, any>();

const middleware = {
  wrapGenerate: async ({ doGenerate, params }: any) => {
    const key = JSON.stringify(params);
    const cached = cache.get(key);
    if (cached) return cached;
    const result = await doGenerate();
    cache.set(key, result);
    return result;
  },
  wrapStream: async ({ doStream, params }: any) => {
    const key = JSON.stringify(params);
    const cached = cache.get(key);
    if (cached) {
      return { stream: simulateReadableStream({ chunks: cached }) };
    }
    const { stream, ...rest } = await doStream();
    const chunks: any[] = [];
    const response = stream.pipeThrough(new TransformStream({
      transform(chunk, controller) { chunks.push(chunk); controller.enqueue(chunk); },
    }));
    cache.set(key, chunks);
    return { stream: response, ...rest };
  },
};

const model = wrapLanguageModel({ model: openai('gpt-4o-mini'), middleware });
await generateText({ model, prompt: 'Say hello.' });

